<div class="interactive-wrapper"><div class="card shadow-sm border-0 mb-4" style="border-radius:24px;background:#fff;word-break:break-word"><div class="bg-white border-bottom-0 py-4 px-4" style="border-radius:24px 24px 0 0"><div class="d-flex align-items-center justify-content-between flex-wrap gap-2"><div class="d-flex align-items-center"><div style="width:48px;height:48px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.25rem;background:#eef2ff"><i class="fas fa-fill-drip text-primary"></i></div><div class="ms-3"><h5 class="mb-0 fw-bold text-dark">Solution Dilution Calc</h5><p class="text-muted small mb-0">Calculate dilution using C₁V₁ = C₂V₂</p></div></div><button class="btn btn-sm rounded-pill px-3" id="btn-reset" style="background:#f1f5f9;font-weight:600"><i class="fas fa-undo me-1"></i>Reset</button></div></div><div class="px-4 pb-4" style="overflow-x:auto"><div class="row g-3"><div class="col-md-3"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">C₁ (M)</label><input type="number" id="in-c1" class="form-control form-control-lg" value="1" step="0.01"></div><div class="col-md-3"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">V₁ (mL)</label><input type="number" id="in-v1" class="form-control form-control-lg" value="" placeholder="?" step="0.1"></div><div class="col-md-3"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">C₂ (M)</label><input type="number" id="in-c2" class="form-control form-control-lg" value="0.1" step="0.01"></div><div class="col-md-3"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">V₂ (mL)</label><input type="number" id="in-v2" class="form-control form-control-lg" value="500" step="0.1"></div></div><div class="mt-4 text-center"><button class="btn btn-primary btn-lg rounded-pill px-5 shadow-sm" id="btn-calc" style="min-width:260px;max-width:100%"><i class="fas fa-calculator me-2"></i>Calculate</button></div><div class="mt-3 p-3 rounded-4 border" style="background:#f8fafc"><p class="mb-0 small text-muted"><i class="fas fa-info-circle text-primary me-2"></i><b>Formula:</b> C₁V₁ = C₂V₂ — leave one field empty to solve</p></div></div></div><div id="res" class="card shadow-sm border-0 d-none mb-4" style="border-radius:24px;background:#fff;word-break:break-word"><div class="bg-white border-bottom-0 py-4 px-4" style="border-radius:24px 24px 0 0"><div class="d-flex align-items-center justify-content-between flex-wrap gap-2"><div class="d-flex align-items-center"><div style="width:48px;height:48px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.25rem;background:#ecfdf5"><i class="fas fa-check-circle text-success"></i></div><div class="ms-3"><h5 class="mb-0 fw-bold text-dark">Result</h5></div></div><button class="btn btn-success btn-sm rounded-pill px-4 shadow-sm" id="btn-copy"><i class="fas fa-copy me-1"></i>Copy</button></div></div><div class="px-4 pb-4" style="overflow-x:auto"><div class="p-4 rounded-4 bg-light border text-center mb-3"><div class="small fw-bold text-uppercase text-muted mb-1">RESULT</div><div class="display-4 fw-bold text-dark" id="out-main">—</div><div class="small text-muted fw-bold" id="out-unit"></div></div><div id="out-detail" class="row g-3 mb-3"></div><div class="p-4 rounded-4 bg-light border"><h6 class="fw-bold mb-2 small text-uppercase text-muted"><i class="fas fa-lightbulb text-warning me-2"></i>Insights</h6><div id="out-ins" class="small"></div></div></div></div></div><style>.form-control-lg,.form-select-lg{border:1.5px solid #e2e8f0;border-radius:12px;font-size:1.05rem;padding:.75rem 1rem}.form-control:focus,.form-select:focus{border-color:#4f46e5;box-shadow:0 0 0 4px rgba(79,70,229,.1)}</style><script>document.addEventListener("DOMContentLoaded",function(){document.getElementById("btn-calc").addEventListener("click",function(){var c1=document.getElementById("in-c1").value,v1=document.getElementById("in-v1").value,c2=document.getElementById("in-c2").value,v2=document.getElementById("in-v2").value;var r,lbl;if(!v1&&c1&&c2&&v2){r=(parseFloat(c2)*parseFloat(v2))/parseFloat(c1);lbl="V₁ = "+r.toFixed(2)+" mL";}else if(!c1&&v1&&c2&&v2){r=(parseFloat(c2)*parseFloat(v2))/parseFloat(v1);lbl="C₁ = "+r.toFixed(4)+" M";}else if(!c2&&c1&&v1&&v2){r=(parseFloat(c1)*parseFloat(v1))/parseFloat(v2);lbl="C₂ = "+r.toFixed(4)+" M";}else if(!v2&&c1&&v1&&c2){r=(parseFloat(c1)*parseFloat(v1))/parseFloat(c2);lbl="V₂ = "+r.toFixed(2)+" mL";}else{document.getElementById("out-main").textContent="Leave one field empty";return;}document.getElementById("out-main").textContent=r.toFixed(4);document.getElementById("out-unit").textContent=lbl;document.getElementById("out-ins").innerHTML="<p>C₁V₁ = C₂V₂ solved: <b>"+lbl+"</b></p>";document.getElementById("res").classList.remove("d-none");});document.getElementById("btn-reset").addEventListener("click",function(){document.getElementById("in-c1").value=1;document.getElementById("in-v1").value="";document.getElementById("in-c2").value=0.1;document.getElementById("in-v2").value=500;document.getElementById("res").classList.add("d-none");});document.getElementById("btn-copy").addEventListener("click",function(){navigator.clipboard.writeText(document.getElementById("out-unit").textContent);var b=this;b.innerHTML="Copied!";setTimeout(function(){b.innerHTML="<i class=\"fas fa-copy me-1\"></i>Copy";},2e3);});});</script><?php /**PATH D:\Xamp\htdocs\ToolsHub\resources\views\tools\interactive\solution-dilution-calc.blade.php ENDPATH**/ ?>